import { relations } from "drizzle-orm";
import { integer, pgTable, varchar } from "drizzle-orm/pg-core";
import { school } from "./school";

/*
CREATE TABLE "school_email_domain" (
    "pk"        integer      GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "school_pk" integer      NOT NULL REFERENCES "school" ("pk"),
    "domain"    varchar(128) NOT NULL UNIQUE
);
*/
// 학교 이메일 인증 시 허용 도메인. 재학생의 학교를 정하는 기준이라 한 도메인은 한 학교에만 속함
export const schoolEmailDomain = pgTable("school_email_domain", {
  pk: integer("pk").primaryKey().generatedByDefaultAsIdentity().notNull(),
  schoolPk: integer("school_pk")
    .notNull()
    .references(() => school.pk),
  domain: varchar("domain", { length: 128 }).notNull().unique(),
});

export const schoolEmailDomainRelations = relations(
  schoolEmailDomain,
  ({ one }) => ({
    school: one(school, {
      fields: [schoolEmailDomain.schoolPk],
      references: [school.pk],
    }),
  }),
);
